       border-radius: 1.5rem;
       box-shadow: var(--shadow);
       padding: 2rem;
     }

     h1 {
       margin: 0 0 0.5rem;
       font-size: clamp(1.6rem, 3vw, 2.1rem);
       line-height: 1.15;
     }

     .subhead {
       margin: 0 0 1.75rem;
       color: var(--muted);
     }

     form {
       display: grid;
       gap: 1.25rem;
     }

     .form-field {
       padding: 1rem;
       border: 1px solid var(--panel-border);
       border-radius: 1rem;
       background: rgba(255, 255, 255, 0.02);
     }

     .checkbox-row {
       display: flex;
       align-items: flex-start;
       gap: 0.75rem;
     }

     input[type="checkbox"] {
       width: 1.125rem;
       height: 1.125rem;
       margin-top: 0.2rem;
       accent-color: var(--accent);
       flex: 0 0 auto;
     }

     label {
       font-weight: 600;
       cursor: pointer;
     }

     .helper-text {
       margin: 0.35rem 0 0;
       color: var(--muted);
       font-size: 0.95rem;
     }

     button {
       appearance: none;
       border: 0;
       border-radius: 0.9rem;
       padding: 0.95rem 1.2rem;
       font: inherit;
       font-weight: 700;
       color: #08101f;
       background: linear-gradient(180deg, var(--accent-strong), var(--accent));
       box-shadow: 0 10px 24px rgba(124, 156, 255, 0.28);
       cursor: pointer;
       transition: transform 0.15s ease, box-shadow 0.15s ease;
     }

     button:hover {
       transform: translateY(-1px);
       box-shadow: 0 14px 28px rgba(124, 156, 255, 0.32);
     }

     button:focus-visible,
     input[type="checkbox"]:focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 3px;
     }

     #status {
       min-height: 1.5rem;
       color: var(--muted);
       font-size: 0.95rem;
     }

     @media (max-width: 480px) {
       .card {
         padding: 1.5rem;
       }
     }

     @media (forced-colors: active) {
       :root {
         --bg: Canvas;
         --panel: Canvas;
         --panel-border: ButtonBorder;
         --text: CanvasText;
         --muted: CanvasText;
         --accent: ButtonFace;
         --accent-strong: ButtonFace;
         --focus: Highlight;
       }

       .skip-link,
       button {
         forced-color-adjust: auto;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>

   <main id="main-content">
     <section class="card" aria-labelledby="consent-title">
       <h1 id="consent-title">Terms of use consent</h1>
       <p class="subhead">Please review and confirm before continuing.</p>

       <form id="consent-form">
         <div class="form-field">
           <div class="checkbox-row">
             <input
               id="agree"
               name="agree"
               type="checkbox"
               required
               aria-describedby="agree-help"
             />
             <div>
               <label for="agree">I agree to the terms of use *</label>
               <p class="helper-text" id="agree-help">You must agree to proceed.</p>
             </div>
           </div>
         </div>

         <button type="submit">Submit</button>
         <p id="status" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('consent-form');
     const checkbox = document.getElementById('agree');
     const status = document.getElementById('status');

     form.addEventListener('submit', (event) => {
       event.preventDefault();
       status.textContent = 'Thanks — your consent has been recorded.';
     });

     checkbox.addEventListener('input', () => {
       status.textContent = '';
     });
   </script>
 </body>
 </html>

